  const credential = new ManagedIdentityCredential({
    clientId: clientId
  });
  return credential;
}

/**
 * User-Assigned Managed Identity using Resource ID
 * Use when you have the full ARM resource ID
 */
export function createUserAssignedCredentialByResourceId(
